import { useCallback, useRef, useState } from "react";

export function useSvgDocument() {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgElRef = useRef<SVGSVGElement | null>(null);
  const [fileName, setFileName] = useState<string>("");
  const [loaded, setLoaded] = useState(false);
  const [revision, setRevision] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const notifyChange = useCallback(() => {
    setRevision((r) => r + 1);
  }, []);

  const loadSvg = useCallback(
    async (file: File) => {
      setError(null);

      if (!file.name.toLowerCase().endsWith(".svg")) {
        setError("SVGファイルのみ対応しています");
        return;
      }

      try {
        const text = await file.text();
        const parser = new DOMParser();
        const doc = parser.parseFromString(text, "image/svg+xml");

        const parseError = doc.querySelector("parsererror");
        if (parseError) {
          setError("SVGファイルの解析に失敗しました");
          return;
        }

        const svg = doc.querySelector("svg");
        if (!svg) {
          setError("有効なSVG要素が見つかりません");
          return;
        }

        // Mount into container
        const container = containerRef.current;
        if (container) {
          container.innerHTML = "";
          const imported = document.importNode(svg, true) as SVGSVGElement;
          container.appendChild(imported);
          svgElRef.current = imported;
        }

        setFileName(file.name);
        setLoaded(true);
        setRevision(0);
        // Trigger initial inspect after mount
        setTimeout(() => notifyChange(), 0);
      } catch {
        setError("ファイルの読み込みに失敗しました");
      }
    },
    [notifyChange],
  );

  return {
    containerRef,
    svgElRef,
    fileName,
    loaded,
    revision,
    error,
    loadSvg,
    notifyChange,
  };
}

