import { useCallback, useEffect, useRef, useState } from "react";
import type { SelectionMode } from "../hooks/useSelection";

const SHAPE_TAGS = new Set([
  "path",
  "rect",
  "circle",
  "ellipse",
  "line",
  "polyline",
  "polygon",
]);

type Props = {
  containerRef: React.RefObject<HTMLDivElement | null>;
  svgElRef: React.RefObject<SVGSVGElement | null>;
  revision: number;
  mode: SelectionMode;
  onClickElement: (el: SVGElement, additive: boolean) => void;
  onLassoSelect: (elements: SVGElement[]) => void;
  onClearSelection: () => void;
};

function findShapeAncestor(el: Element): SVGElement | null {
  let cur: Element | null = el;
  while (cur) {
    if (SHAPE_TAGS.has(cur.tagName.toLowerCase())) {
      return cur as SVGElement;
    }
    cur = cur.parentElement;
  }
  return null;
}

export function Preview({
  containerRef,
  svgElRef,
  revision,
  mode,
  onClickElement,
  onLassoSelect,
  onClearSelection,
}: Props) {
  const lassoRef = useRef<SVGPolylineElement | null>(null);
  const [lassoPoints, setLassoPoints] = useState<string>("");
  const [isDrawing, setIsDrawing] = useState(false);
  const pointsRef = useRef<{ x: number; y: number }[]>([]);

  const handleClick = useCallback(
    (e: React.MouseEvent) => {
      if (mode !== "click") return;
      const target = e.target as Element;
      const shape = findShapeAncestor(target);
      if (shape) {
        onClickElement(shape, e.shiftKey);
      } else {
        onClearSelection();
      }
    },
    [mode, onClickElement, onClearSelection],
  );

  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      if (mode !== "lasso") return;
      setIsDrawing(true);
      pointsRef.current = [{ x: e.nativeEvent.offsetX, y: e.nativeEvent.offsetY }];
      setLassoPoints(
        `${e.nativeEvent.offsetX},${e.nativeEvent.offsetY}`,
      );
    },
    [mode],
  );

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      if (!isDrawing) return;
      pointsRef.current.push({
        x: e.nativeEvent.offsetX,
        y: e.nativeEvent.offsetY,
      });
      setLassoPoints(
        pointsRef.current.map((p) => `${p.x},${p.y}`).join(" "),
      );
    },
    [isDrawing],
  );

  const handleMouseUp = useCallback(() => {
    if (!isDrawing) return;
    setIsDrawing(false);

    const svg = svgElRef.current;
    if (!svg || pointsRef.current.length < 3) {
      setLassoPoints("");
      return;
    }

    // Compute bounding box of lasso
    const pts = pointsRef.current;
    const minX = Math.min(...pts.map((p) => p.x));
    const maxX = Math.max(...pts.map((p) => p.x));
    const minY = Math.min(...pts.map((p) => p.y));
    const maxY = Math.max(...pts.map((p) => p.y));

    // Find elements within lasso bounding box
    const container = containerRef.current;
    if (!container) return;
    const containerRect = container.getBoundingClientRect();

    const selector = Array.from(SHAPE_TAGS).join(",");
    const elements = svg.querySelectorAll(selector);
    const selected: SVGElement[] = [];

    for (const el of elements) {
      const elRect = (el as SVGElement).getBoundingClientRect();
      const relX = elRect.left - containerRect.left;
      const relY = elRect.top - containerRect.top;
      const relRight = relX + elRect.width;
      const relBottom = relY + elRect.height;

      // Check overlap with lasso bbox
      if (relRight >= minX && relX <= maxX && relBottom >= minY && relY <= maxY) {
        selected.push(el as SVGElement);
      }
    }

    onLassoSelect(selected);
    setLassoPoints("");
    pointsRef.current = [];
  }, [isDrawing, svgElRef, containerRef, onLassoSelect]);

  // Fit SVG to container whenever SVG changes
  useEffect(() => {
    const svg = svgElRef.current;
    if (!svg) return;
    // Let the SVG's intrinsic aspect ratio determine size,
    // constrained to not exceed the container in either dimension
    svg.style.display = "block";
    svg.style.width = "auto";
    svg.style.height = "auto";
    svg.style.maxWidth = "100%";
    svg.style.maxHeight = "100%";
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
  }, [svgElRef, revision]);

  return (
    <div className="relative w-full h-full bg-white rounded-lg overflow-hidden">
      {/* Checkerboard background for transparency */}
      <div
        className="absolute inset-0"
        style={{
          backgroundImage:
            "linear-gradient(45deg, #f0f0f0 25%, transparent 25%), linear-gradient(-45deg, #f0f0f0 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #f0f0f0 75%), linear-gradient(-45deg, transparent 75%, #f0f0f0 75%)",
          backgroundSize: "20px 20px",
          backgroundPosition: "0 0, 0 10px, 10px -10px, -10px 0px",
        }}
      />
      <div
        ref={containerRef}
        className="relative w-full h-full flex items-center justify-center p-4"
        onClick={handleClick}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
      />
      {/* Lasso overlay */}
      {lassoPoints && (
        <svg className="absolute inset-0 w-full h-full pointer-events-none">
          <polyline
            ref={lassoRef}
            points={lassoPoints}
            fill="rgba(59, 130, 246, 0.1)"
            stroke="#3b82f6"
            strokeWidth="1"
            strokeDasharray="4"
          />
        </svg>
      )}
    </div>
  );
}

import { useState } from "react";
import type { InspectResult } from "../hooks/useInspect";

type ColorMode = "cmyk" | "rgb";

type Props = {
  result: InspectResult;
  smallPathCount: number;
  onSelectColor: (elements: SVGElement[]) => void;
  onHighlightSmallPaths: () => void;
  onDeleteSmallPaths: () => void;
};

export function InspectPanel({
  result,
  smallPathCount,
  onSelectColor,
  onHighlightSmallPaths,
  onDeleteSmallPaths,
}: Props) {
  const [colorMode, setColorMode] = useState<ColorMode>("cmyk");

  return (
    <div className="space-y-4">
      <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
        Inspect
      </h3>

      {/* Document info */}
      <div className="space-y-1 text-xs">
        <div className="flex justify-between">
          <span className="text-gray-500">サイズ (px)</span>
          <span>
            {result.width} × {result.height}
          </span>
        </div>
        <div className="flex justify-between">
          <span className="text-gray-500">サイズ (mm)</span>
          <span>
            {result.widthMm} × {result.heightMm}
          </span>
        </div>
        {result.viewBox && (
          <div className="flex justify-between">
            <span className="text-gray-500">viewBox</span>
            <span className="truncate ml-2 text-right">{result.viewBox}</span>
          </div>
        )}
        <div className="flex justify-between">
          <span className="text-gray-500">総パス数</span>
          <span>
            {result.totalPaths}
            {result.totalPaths > 1000 && (
              <span className="ml-1 px-1 py-0.5 bg-yellow-100 text-yellow-800 rounded text-[10px]">
                注意
              </span>
            )}
          </span>
        </div>
      </div>

      {/* Color palette */}
      <div>
        <div className="flex items-center justify-between mb-2">
          <h4 className="text-xs font-medium text-gray-600">
            色パレット ({result.colors.length}色)
          </h4>
          <div className="flex text-[10px] border border-gray-300 rounded overflow-hidden">
            <button
              onClick={() => setColorMode("cmyk")}
              className={`px-1.5 py-0.5 ${colorMode === "cmyk" ? "bg-gray-200 font-medium" : "hover:bg-gray-50"}`}
            >
              CMYK
            </button>
            <button
              onClick={() => setColorMode("rgb")}
              className={`px-1.5 py-0.5 border-l border-gray-300 ${colorMode === "rgb" ? "bg-gray-200 font-medium" : "hover:bg-gray-50"}`}
            >
              RGB
            </button>
          </div>
        </div>
        <div className="space-y-1.5">
          {result.colors.map((c) => (
            <div
              key={c.hex}
              className="flex items-center gap-2 text-[11px] group"
            >
              <span
                className="w-4 h-4 rounded border border-gray-300 flex-shrink-0"
                style={{ backgroundColor: c.hex }}
              />
              <div className="flex-1 min-w-0">
                <div className="font-mono">{c.hex}</div>
                <div className="text-gray-400">
                  {colorMode === "cmyk"
                    ? `C${c.cmyk.c} M${c.cmyk.m} Y${c.cmyk.y} K${c.cmyk.k}`
                    : `rgb(${c.rgb.r}, ${c.rgb.g}, ${c.rgb.b})`}
                </div>
              </div>
              <span className="text-gray-400 flex-shrink-0">{c.count}</span>
              <button
                onClick={() => onSelectColor(c.elements)}
                className="text-blue-500 hover:text-blue-700 opacity-0 group-hover:opacity-100 flex-shrink-0"
              >
                全選択
              </button>
            </div>
          ))}
        </div>
        {result.colors.length > 0 && colorMode === "cmyk" && (
          <p className="text-[10px] text-gray-400 mt-1">
            ※ CMYK値は近似値です
          </p>
        )}
      </div>

      {/* Small paths */}
      <div className="space-y-1">
        <div className="flex items-center gap-2">
          <span className="text-xs text-gray-600">孤立点・小パス</span>
          {smallPathCount > 0 && (
            <span className="px-1.5 py-0.5 bg-orange-100 text-orange-700 rounded text-[10px] font-medium">
              {smallPathCount}件
            </span>
          )}
          {smallPathCount === 0 && (
            <span className="text-[10px] text-gray-400">なし</span>
          )}
        </div>
        {smallPathCount > 0 && (
          <div className="flex gap-1">
            <button
              onClick={onHighlightSmallPaths}
              className="text-[11px] px-2 py-1 border border-gray-300 rounded hover:bg-gray-50"
            >
              ハイライト
            </button>
            <button
              onClick={onDeleteSmallPaths}
              className="text-[11px] px-2 py-1 border border-red-300 text-red-600 rounded hover:bg-red-50"
            >
              削除
            </button>
          </div>
        )}
      </div>

      {/* Stroke detection */}
      <div className="space-y-1">
        <div className="flex items-center gap-2">
          <span className="text-xs text-gray-600">ストローク</span>
          {result.strokeCount > 0 ? (
            <span className="px-1.5 py-0.5 bg-blue-100 text-blue-700 rounded text-[10px] font-medium">
              {result.strokeCount}件
            </span>
          ) : (
            <span className="text-[10px] text-gray-400">なし</span>
          )}
        </div>
      </div>
    </div>
  );
}

