            onClick={handleExport}
            disabled={!loaded}
            className="text-xs px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-40 disabled:cursor-not-allowed"
          >
            エクスポート
          </button>
        </div>
