import paper from "paper";

/**
 * Outline all stroked paths in the SVG using paper.js + paperjs-offset.
 * Each stroked path is replaced with a filled outline path.
 * If the original path had both fill and stroke, two paths are generated.
 */
export async function outlineStrokes(svgEl: SVGSVGElement): Promise<void> {
  // Setup paper.js with an offscreen canvas
  const canvas = document.createElement("canvas");
  canvas.width = 1;
  canvas.height = 1;
  paper.setup(canvas);

  // Load paperjs-offset (it extends paper.Path prototype)
  await import("paperjs-offset");

  // Import SVG into paper.js
  const svgString = new XMLSerializer().serializeToString(svgEl);
  const imported = paper.project.importSVG(svgString);

  // Collect all paths with strokes
  const paths = imported.getItems({ recursive: true }).filter(
    (item): item is paper.Path =>
      item instanceof paper.Path &&
      item.strokeWidth > 0 &&
      item.strokeColor !== null &&
      item.strokeColor !== undefined,
  );

  for (const path of paths) {
    const strokeWidth = path.strokeWidth;
    const strokeColor = path.strokeColor;
    const strokeCap = path.strokeCap;
    const strokeJoin = path.strokeJoin;
    const miterLimit = path.miterLimit;
    const hasFill =
      path.fillColor !== null &&
      path.fillColor !== undefined &&
      path.fillColor.alpha > 0;

    try {
      // Use paperjs-offset's offsetStroke to create the outline
      // offsetStroke is added to Path.prototype by the plugin
      const outlined = (path as paper.Path & {
        offsetStroke(offset: number, options?: object): paper.Path;
      }).offsetStroke(strokeWidth / 2, {
        join: strokeJoin || "miter",
        cap: strokeCap || "butt",
        limit: miterLimit || 10,
      });

      if (outlined) {
        // Set the outline fill to the original stroke color
        outlined.fillColor = strokeColor;
        outlined.strokeWidth = 0;
        outlined.strokeColor = null;

        // Insert outline near the original path
        if (path.parent) {
          path.parent.insertChild(path.index + 1, outlined);
        }

        if (hasFill) {
          // Keep original path but remove its stroke
          path.strokeWidth = 0;
          path.strokeColor = null;
        } else {
          // No fill — just remove the original
          path.remove();
        }
      }
    } catch (err) {
      console.warn("Failed to outline stroke for path:", err);
      // Fallback: just remove stroke attributes and set fill
      if (strokeColor) {
        if (!hasFill) {
          path.fillColor = strokeColor;
        }
        path.strokeWidth = 0;
        path.strokeColor = null;
      }
    }
  }

  // Export the modified SVG back
  const exportedSvg = paper.project.exportSVG({ asString: true }) as string;
  paper.project.clear();

  // Parse and replace in the original DOM
  const parser = new DOMParser();
  const doc = parser.parseFromString(exportedSvg, "image/svg+xml");
  const newSvgContent = doc.querySelector("svg");
  if (!newSvgContent) return;

  // Preserve original viewBox
  const viewBox = svgEl.getAttribute("viewBox");

  // Replace children of the original SVG element
  while (svgEl.firstChild) {
    svgEl.removeChild(svgEl.firstChild);
  }

  // Copy children from exported SVG
  while (newSvgContent.firstChild) {
    svgEl.appendChild(svgEl.ownerDocument.importNode(newSvgContent.firstChild, true));
  }

  // Restore viewBox if it was lost
  if (viewBox) {
    svgEl.setAttribute("viewBox", viewBox);
  }
}

