import paper from "paper";

// Ensure paper.js is set on window for paperjs-offset
declare global {
  interface Window {
    paper?: typeof paper;
  }
}

/**
 * Outline all stroked paths in the SVG using paper.js + paperjs-offset.
 * Each stroked path is replaced with a filled outline path.
 */
export async function outlineStrokes(svgEl: SVGSVGElement): Promise<void> {
  // Setup paper.js with an offscreen canvas
  const canvas = document.createElement("canvas");
  canvas.width = 1;
  canvas.height = 1;
  paper.setup(canvas);

  // Make paper available globally for paperjs-offset
  window.paper = paper;
  await import("paperjs-offset");

  const viewBox = svgEl.getAttribute("viewBox");

  // Find all stroked elements in the DOM
  const selector = "path,rect,circle,ellipse,line,polyline,polygon";
  const elements = Array.from(svgEl.querySelectorAll(selector)) as SVGElement[];

  const stroked = elements.filter((el) => {
    const stroke = el.getAttribute("stroke") || el.style.stroke || "";
    const strokeWidth = parseFloat(
      el.getAttribute("stroke-width") || el.style.strokeWidth || "0",
    );
    return stroke && stroke !== "none" && strokeWidth > 0;
  });

  if (stroked.length === 0) {
    paper.project.clear();
    return;
  }

  for (const el of stroked) {
    try {
      processElement(el, svgEl);
    } catch (err) {
      console.warn("Failed to outline stroke for element:", err);
      // Fallback: just move stroke color to fill and remove stroke
      fallbackConvert(el);
    }
  }

  paper.project.clear();

  // Restore viewBox
  if (viewBox) svgEl.setAttribute("viewBox", viewBox);
}

function processElement(el: SVGElement, svgRoot: SVGSVGElement): void {
  const strokeColor = el.getAttribute("stroke") || el.style.stroke;
  const strokeWidth = parseFloat(
    el.getAttribute("stroke-width") || el.style.strokeWidth || "1",
  );
  const fillColor = el.getAttribute("fill") || el.style.fill || "";
  const hasFill = fillColor && fillColor !== "none" && fillColor !== "transparent";
  const strokeCap = el.getAttribute("stroke-linecap") || "butt";
  const strokeJoin = el.getAttribute("stroke-linejoin") || "miter";
  const miterLimit = parseFloat(el.getAttribute("stroke-miterlimit") || "10");

  // Create a temporary SVG string for just this element to import into paper.js
  const tempSvg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  tempSvg.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  const vb = svgRoot.getAttribute("viewBox");
  if (vb) tempSvg.setAttribute("viewBox", vb);

  const clone = el.cloneNode(true) as SVGElement;
  // Remove any transform — we want to work in the element's local coords
  tempSvg.appendChild(clone);

  paper.project.clear();
  const imported = paper.project.importSVG(tempSvg);

  // Find the imported path
  const paths = imported.getItems({ recursive: true }).filter(
    (item): item is paper.Path => item instanceof paper.Path,
  );

  if (paths.length === 0) {
    imported.remove();
    return;
  }

  const paperPath = paths[0];

  // Use PaperOffset.offsetStroke via the prototype extension
  type PathWithOffset = paper.Path & {
    offsetStroke(offset: number, options?: {
      join?: string; cap?: string; limit?: number;
    }): paper.Path | paper.CompoundPath;
  };

  const outlined = (paperPath as PathWithOffset).offsetStroke(strokeWidth / 2, {
    join: strokeJoin,
    cap: strokeCap,
    limit: miterLimit,
  });

  if (!outlined) {
    imported.remove();
    fallbackConvert(el);
    return;
  }

  // Export the outlined path as SVG path data
  const exportedSvg = outlined.exportSVG({ asString: false }) as SVGElement;
  const outlinedD = exportedSvg.getAttribute("d");

  if (!outlinedD) {
    imported.remove();
    fallbackConvert(el);
    return;
  }

  // Create the outline <path> in the real DOM
  const outlinePath = svgRoot.ownerDocument.createElementNS(
    "http://www.w3.org/2000/svg",
    "path",
  );
  outlinePath.setAttribute("d", outlinedD);
  outlinePath.setAttribute("fill", strokeColor || "#000000");
  outlinePath.removeAttribute("stroke");

  // Copy opacity if present
  const opacity = el.getAttribute("opacity");
  if (opacity) outlinePath.setAttribute("opacity", opacity);
  const strokeOpacity = el.getAttribute("stroke-opacity");
  if (strokeOpacity) outlinePath.setAttribute("opacity", strokeOpacity);

  // Insert outline after the original element
  el.parentNode?.insertBefore(outlinePath, el.nextSibling);

  if (hasFill) {
    // Keep the original element but remove stroke
    el.removeAttribute("stroke");
    el.removeAttribute("stroke-width");
    el.removeAttribute("stroke-linecap");
    el.removeAttribute("stroke-linejoin");
    el.removeAttribute("stroke-dasharray");
    el.removeAttribute("stroke-dashoffset");
    el.removeAttribute("stroke-miterlimit");
    el.removeAttribute("stroke-opacity");
    el.style.stroke = "";
    el.style.strokeWidth = "";
  } else {
    // No fill — remove original, outline replaces it
    el.remove();
  }

  imported.remove();
}

function fallbackConvert(el: SVGElement): void {
  const strokeColor = el.getAttribute("stroke") || el.style.stroke;
  const fillColor = el.getAttribute("fill") || el.style.fill || "";
  const hasFill = fillColor && fillColor !== "none" && fillColor !== "transparent";

  if (!hasFill && strokeColor) {
    el.setAttribute("fill", strokeColor);
  }
  el.removeAttribute("stroke");
  el.removeAttribute("stroke-width");
  el.removeAttribute("stroke-linecap");
  el.removeAttribute("stroke-linejoin");
  el.removeAttribute("stroke-dasharray");
  el.removeAttribute("stroke-dashoffset");
  el.removeAttribute("stroke-miterlimit");
  el.removeAttribute("stroke-opacity");
  el.style.stroke = "";
  el.style.strokeWidth = "";
}

