/**
 * Outline all stroked paths in the SVG by sampling the path centerline
 * and generating offset outline paths using browser SVG APIs.
 * No external dependencies needed.
 */
export async function outlineStrokes(svgEl: SVGSVGElement): Promise<void> {
  const viewBox = svgEl.getAttribute("viewBox");

  const selector = "path,rect,circle,ellipse,line,polyline,polygon";
  const elements = Array.from(svgEl.querySelectorAll(selector)) as SVGElement[];

  const stroked = elements.filter((el) => {
    const stroke = el.getAttribute("stroke") || el.style.stroke || "";
    const sw = parseFloat(el.getAttribute("stroke-width") || el.style.strokeWidth || "0");
    return stroke && stroke !== "none" && sw > 0;
  });

  if (stroked.length === 0) return;

  for (const el of stroked) {
    try {
      outlineElement(el, svgEl);
    } catch (err) {
      console.warn("Failed to outline stroke:", err);
      fallbackConvert(el);
    }
  }

  if (viewBox) svgEl.setAttribute("viewBox", viewBox);
}

/**
 * Convert a single stroked element to filled outline path(s).
 * Uses a temporary <path> in the DOM to access getTotalLength/getPointAtLength.
 */
function outlineElement(el: SVGElement, svgRoot: SVGSVGElement): void {
  const strokeColor = el.getAttribute("stroke") || el.style.stroke || "#000";
  const strokeWidth = parseFloat(
    el.getAttribute("stroke-width") || el.style.strokeWidth || "1",
  );
  const fillVal = el.getAttribute("fill") || el.style.fill || "";
  const hasFill = fillVal && fillVal !== "none" && fillVal !== "transparent";
  const cap = el.getAttribute("stroke-linecap") || "butt";

  // We need a <path> element in the DOM to use getTotalLength / getPointAtLength.
  // Convert shape elements to path d-attribute if needed.
  let pathEl: SVGPathElement;
  let tempPath = false;

  if (el instanceof SVGPathElement) {
    pathEl = el;
  } else {
    // Create a temporary <path> from the shape
    const d = shapeToD(el);
    if (!d) {
      fallbackConvert(el);
      return;
    }
    pathEl = svgRoot.ownerDocument.createElementNS("http://www.w3.org/2000/svg", "path");
    pathEl.setAttribute("d", d);
    // Copy transform if any
    const t = el.getAttribute("transform");
    if (t) pathEl.setAttribute("transform", t);
    // Must be in DOM for getPointAtLength to work
    svgRoot.appendChild(pathEl);
    tempPath = true;
  }

  const totalLength = pathEl.getTotalLength();
  if (totalLength === 0) {
    if (tempPath) pathEl.remove();
    fallbackConvert(el);
    return;
  }

  // Detect if path is closed
  const d = pathEl.getAttribute("d") || "";
  const isClosed = /[Zz]\s*$/.test(d.trim());

  // Sample points along the path
  const halfW = strokeWidth / 2;
  const step = Math.max(0.5, Math.min(strokeWidth / 4, 2));
  const numSamples = Math.max(Math.ceil(totalLength / step), 2);

  const leftPoints: { x: number; y: number }[] = [];
  const rightPoints: { x: number; y: number }[] = [];

  for (let i = 0; i <= numSamples; i++) {
    const len = (i / numSamples) * totalLength;
    const pt = pathEl.getPointAtLength(len);

    // Get tangent by sampling nearby points
    const eps = 0.1;
    const ptBefore = pathEl.getPointAtLength(Math.max(0, len - eps));
    const ptAfter = pathEl.getPointAtLength(Math.min(totalLength, len + eps));

    let tx = ptAfter.x - ptBefore.x;
    let ty = ptAfter.y - ptBefore.y;
    const tLen = Math.sqrt(tx * tx + ty * ty);
    if (tLen === 0) continue;
    tx /= tLen;
    ty /= tLen;

    // Normal = perpendicular to tangent
    const nx = -ty;
    const ny = tx;

    leftPoints.push({ x: pt.x + nx * halfW, y: pt.y + ny * halfW });
    rightPoints.push({ x: pt.x - nx * halfW, y: pt.y - ny * halfW });
  }

  if (leftPoints.length < 2) {
    if (tempPath) pathEl.remove();
    fallbackConvert(el);
    return;
  }

  // Build outline path
  let outlineD: string;

  if (isClosed) {
    // Closed path: outer loop forward, inner loop backward
    outlineD = buildClosedOutline(leftPoints, rightPoints);
  } else {
    // Open path: forward along left, end cap, backward along right, start cap
    outlineD = buildOpenOutline(leftPoints, rightPoints, cap, halfW, pathEl, totalLength);
  }

  // Create outline path element
  const outlinePath = svgRoot.ownerDocument.createElementNS(
    "http://www.w3.org/2000/svg",
    "path",
  );
  outlinePath.setAttribute("d", outlineD);
  outlinePath.setAttribute("fill", strokeColor);

  const opacity = el.getAttribute("opacity");
  if (opacity) outlinePath.setAttribute("opacity", opacity);
  const strokeOpacity = el.getAttribute("stroke-opacity");
  if (strokeOpacity) outlinePath.setAttribute("fill-opacity", strokeOpacity);

  // Copy transform from original if it's a path (shapes already have it baked in via shapeToD)
  if (!tempPath) {
    const t = el.getAttribute("transform");
    if (t) outlinePath.setAttribute("transform", t);
  }

  // Insert after original
  el.parentNode?.insertBefore(outlinePath, el.nextSibling);

  if (tempPath) pathEl.remove();

  if (hasFill) {
    removeStrokeAttrs(el);
  } else {
    el.remove();
  }
}

function buildClosedOutline(
  left: { x: number; y: number }[],
  right: { x: number; y: number }[],
): string {
  const parts: string[] = [];
  // Outer ring (left points)
  parts.push(`M${r(left[0].x)} ${r(left[0].y)}`);
  for (let i = 1; i < left.length; i++) {
    parts.push(`L${r(left[i].x)} ${r(left[i].y)}`);
  }
  parts.push("Z");
  // Inner ring (right points reversed) — creates hole with evenodd
  parts.push(`M${r(right[0].x)} ${r(right[0].y)}`);
  for (let i = right.length - 1; i >= 0; i--) {
    parts.push(`L${r(right[i].x)} ${r(right[i].y)}`);
  }
  parts.push("Z");
  return parts.join(" ");
}

function buildOpenOutline(
  left: { x: number; y: number }[],
  right: { x: number; y: number }[],
  cap: string,
  halfW: number,
  pathEl: SVGPathElement,
  totalLength: number,
): string {
  const parts: string[] = [];

  // Forward along left side
  parts.push(`M${r(left[0].x)} ${r(left[0].y)}`);
  for (let i = 1; i < left.length; i++) {
    parts.push(`L${r(left[i].x)} ${r(left[i].y)}`);
  }

  // End cap
  if (cap === "round") {
    const lastRight = right[right.length - 1];
    parts.push(`A${r(halfW)} ${r(halfW)} 0 0 1 ${r(lastRight.x)} ${r(lastRight.y)}`);
  } else if (cap === "square") {
    // Extend by halfW in tangent direction
    const eps = 0.1;
    const ptBefore = pathEl.getPointAtLength(Math.max(0, totalLength - eps));
    let tx = endPt.x - ptBefore.x;
    let ty = endPt.y - ptBefore.y;
    const tl = Math.sqrt(tx * tx + ty * ty) || 1;
    tx /= tl;
    ty /= tl;
    const lastLeft = left[left.length - 1];
    const lastRight = right[right.length - 1];
    parts.push(`L${r(lastLeft.x + tx * halfW)} ${r(lastLeft.y + ty * halfW)}`);
    parts.push(`L${r(lastRight.x + tx * halfW)} ${r(lastRight.y + ty * halfW)}`);
  }

  // Backward along right side
  for (let i = right.length - 1; i >= 0; i--) {
    parts.push(`L${r(right[i].x)} ${r(right[i].y)}`);
  }

  // Start cap
  const startPt = pathEl.getPointAtLength(0);
  if (cap === "round") {
    parts.push(`A${r(halfW)} ${r(halfW)} 0 0 1 ${r(left[0].x)} ${r(left[0].y)}`);
  } else if (cap === "square") {
    const ptAfter = pathEl.getPointAtLength(Math.min(totalLength, 0.1));
    let tx = startPt.x - ptAfter.x;
    let ty = startPt.y - ptAfter.y;
    const tl = Math.sqrt(tx * tx + ty * ty) || 1;
    tx /= tl;
    ty /= tl;
    parts.push(`L${r(right[0].x + tx * halfW)} ${r(right[0].y + ty * halfW)}`);
    parts.push(`L${r(left[0].x + tx * halfW)} ${r(left[0].y + ty * halfW)}`);
  }

  parts.push("Z");
  return parts.join(" ");
}

function r(v: number): number {
  return Math.round(v * 100) / 100;
}

/** Convert basic SVG shapes to path d-attribute */
function shapeToD(el: SVGElement): string | null {
  const tag = el.tagName.toLowerCase();
  const a = (name: string) => parseFloat(el.getAttribute(name) || "0");

  switch (tag) {
    case "rect": {
      const x = a("x"), y = a("y"), w = a("width"), h = a("height");
      return `M${x} ${y}L${x + w} ${y}L${x + w} ${y + h}L${x} ${y + h}Z`;
    }
    case "circle": {
      const cx = a("cx"), cy = a("cy"), cr = a("r");
      return `M${cx - cr} ${cy}A${cr} ${cr} 0 1 1 ${cx + cr} ${cy}A${cr} ${cr} 0 1 1 ${cx - cr} ${cy}Z`;
    }
    case "ellipse": {
      const cx = a("cx"), cy = a("cy"), rx = a("rx"), ry = a("ry");
      return `M${cx - rx} ${cy}A${rx} ${ry} 0 1 1 ${cx + rx} ${cy}A${rx} ${ry} 0 1 1 ${cx - rx} ${cy}Z`;
    }
    case "line":
      return `M${a("x1")} ${a("y1")}L${a("x2")} ${a("y2")}`;
    case "polyline":
    case "polygon": {
      const pts = el.getAttribute("points")?.trim();
      if (!pts) return null;
      const nums = pts.split(/[\s,]+/).map(Number);
      if (nums.length < 4) return null;
      const segs = [`M${nums[0]} ${nums[1]}`];
      for (let i = 2; i < nums.length; i += 2) segs.push(`L${nums[i]} ${nums[i + 1]}`);
      if (tag === "polygon") segs.push("Z");
      return segs.join(" ");
    }
    default:
      return null;
  }
}

function removeStrokeAttrs(el: SVGElement): void {
  for (const attr of [
    "stroke", "stroke-width", "stroke-linecap", "stroke-linejoin",
    "stroke-dasharray", "stroke-dashoffset", "stroke-miterlimit", "stroke-opacity",
  ]) {
    el.removeAttribute(attr);
  }
  el.style.stroke = "";
  el.style.strokeWidth = "";
}

function fallbackConvert(el: SVGElement): void {
  const strokeColor = el.getAttribute("stroke") || el.style.stroke;
  const fillVal = el.getAttribute("fill") || el.style.fill || "";
  const hasFill = fillVal && fillVal !== "none" && fillVal !== "transparent";
  if (!hasFill && strokeColor) {
    el.setAttribute("fill", strokeColor);
  }
  removeStrokeAttrs(el);
}

