        return f !== "none" && f !== "";
      })
      .map((p) => (p.getAttribute("d") || "").length);
  });

  // Each outline path should have substantial path data (> 20 chars)
  for (const len of pathLengths) {
    expect(len).toBeGreaterThan(20);
  }
});

